import{c as e}from"./app.756eaed4.js";import{_ as t}from"./plugin-vue_export-helper.21dcd24c.js";const s={},o=e('<h1 id="exploring-the-user-interface" tabindex="-1"><a class="header-anchor" href="#exploring-the-user-interface" aria-hidden="true">#</a> Exploring the User Interface</h1><h2 id="welcome-page" tabindex="-1"><a class="header-anchor" href="#welcome-page" aria-hidden="true">#</a> Welcome Page</h2><p>A welcome page is shown the first time the IMS Explorer for VS Code extension is launched. It provides quick-start scenarios to help verify that the extension is properly installed and to prepare your first project workspace and configurations.</p><h2 id="ims-explorer-views-and-controls" tabindex="-1"><a class="header-anchor" href="#ims-explorer-views-and-controls" aria-hidden="true">#</a> IMS Explorer Views and Controls</h2><blockquote><p><strong>Note:</strong> Source and DDL views display a snapshot of the current state that can be edited within the editor. If you edit these files, the views will not automatically refresh another.</p></blockquote><h3 id="ims-connections-tree-view" tabindex="-1"><a class="header-anchor" href="#ims-connections-tree-view" aria-hidden="true">#</a> IMS Connections Tree View</h3><ul><li><strong>Purpose:</strong> Add and manage multiple IMS database and catalog connections.</li><li><strong>Usage:</strong><ul><li>Add and organize connections.</li><li>Expand/collapse connection contents to browse <strong>DBDs</strong>, <strong>PSBs</strong>, and <strong>PCBs</strong>.</li><li>Right\u2011click an item to view <strong>DDL</strong>, <strong>segments</strong>, <strong>fields</strong>, <strong>source</strong>, or <strong>visualize</strong> the structure.</li></ul></li></ul><h3 id="ims-projects-view" tabindex="-1"><a class="header-anchor" href="#ims-projects-view" aria-hidden="true">#</a> IMS Projects View</h3><ul><li><strong>Purpose:</strong> Create and edit IMS projects to execute SQL queries, run IMS commands, and edit DBD fields and database definitions.</li><li><strong>Usage:</strong> Start new projects, add SQL query files, add IMS command files, import DBDs and PSBs from the IMS catalog, edit DDL and source files, and organize project assets.</li></ul><h3 id="source-and-ddl-views" tabindex="-1"><a class="header-anchor" href="#source-and-ddl-views" aria-hidden="true">#</a> Source and DDL Views</h3><ul><li><strong>Purpose:</strong> View and edit the source code or DDL for DBDs and PSBs.</li><li><strong>Usage:</strong> Right-click a DBD or PSB in the IMS Connections tree view or IMS Projects view and select <strong>View Source</strong> or <strong>View DDL</strong> to open an editable snapshot in the editor.</li><li><strong>Limitation:</strong> These views show a snapshot that can be edited but will not auto-refresh when changes are made. Close and reopen to see updates.</li></ul><h3 id="table-views" tabindex="-1"><a class="header-anchor" href="#table-views" aria-hidden="true">#</a> Table Views</h3><ul><li><strong>Purpose:</strong> Inspect DBDs, PSBs, and PCBs in tabular form.</li><li><strong>Usage:</strong> Quickly click across related definitions to find associated segments and fields. For DBDs and PSBs, select the overflow menu to use <strong>Find referenced PSBs</strong> or <strong>Find referenced DBDs</strong> and view results in a nested table.</li></ul><h3 id="visualization-views" tabindex="-1"><a class="header-anchor" href="#visualization-views" aria-hidden="true">#</a> Visualization Views</h3><ul><li><strong>Purpose:</strong> Interactively explore DBD and PSB hierarchical structures.</li><li><strong>Usage:</strong> Visualize database structures with zoom controls, expand segments to view fields, and switch between visualization, source, DDL, and table views.</li></ul><h3 id="output-channels" tabindex="-1"><a class="header-anchor" href="#output-channels" aria-hidden="true">#</a> Output Channels</h3><ul><li><strong>IBM IMS Explorer for VS Code</strong> \u2014 Client logs</li><li><strong>IBM IMS Explorer LSP Server</strong> \u2014 Language server logs<br> View them via the <strong>Output</strong> panel to troubleshoot or monitor activity.</li></ul><h3 id="status-bar-options" tabindex="-1"><a class="header-anchor" href="#status-bar-options" aria-hidden="true">#</a> Status Bar Options</h3><ul><li><strong>IMS Workspace</strong> \u2014 Indicates the workspace location that stores extension artifacts such as <code>ims.connections.json</code>. Can be clicked to choose a location.</li><li><strong>IMS Connection</strong> \u2014 Used to verify or switch the active database connection for SQL execution.</li></ul><h3 id="settings-integration" tabindex="-1"><a class="header-anchor" href="#settings-integration" aria-hidden="true">#</a> Settings Integration</h3><p>While not indicated on the UI, these extension settings are key to using the IMS Explorer for VS Code extension effectively.</p><ul><li><strong>Java selection</strong> (<code>ims.explorer.connection.property.javaHome</code>) and <strong>JVM arguments</strong> (<code>ims.explorer.connection.property.jvmArgs</code>).</li><li><strong>Logging level</strong> (<code>ims.explorer.logging.level</code>).</li><li><strong>IMS Workspace path</strong> (<code>ims.explorer.property.ImsWorkspace</code>). Configure under <strong>Preferences \u2192 Settings</strong>.</li></ul>',22);function r(n,i){return o}var d=t(s,[["render",r]]);export{d as default};
